	end
	if (#list == 0) then
		local coinContainer = self.Services.Workspace:FindFirstChild("CoinContainer", true);
		if coinContainer then
			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA("BasePart") and c.Parent and not c:GetAttribute(LUAOBFUSACTOR_DECRYPT_STR_0("\217\76\127\237\31\253\149\255\71", "\225\154\35\19\129\122\158"))) then
					table.insert(list, c);
				elseif (c:IsA("Model") and c.Parent) then
					local p = c.PrimaryPart or c:FindFirstChildWhichIsA("BasePart");
					if (p and not p:GetAttribute("Collected")) then
						table.insert(list, p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\120\1\248\82\197\230\194\32", "\84\58\96\139\55\149\135\176")) and p:FindFirstChildOfClass("TouchTransmitter")) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
Hub.FireCoinTouch = function(self, coin)
	if (type(firetouchinterest) ~= "function") then
		return;
	end
	if (not coin or not coin.Parent) then
		return;
	end
	local now = os.clock();
	if ((now - (self.AutoFarm.LastTouch or 0)) < 0.05) then
		return;
	end
	self.AutoFarm.LastTouch = now;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if not root then
		return;
	end
	for _, p in ipairs(self:GetTouchTargets(coin)) do
		pcall(firetouchinterest, root, p, 0);
		pcall(firetouchinterest, root, p, 1);
	end
end;
Hub.GetMurdererHRP = function(self)
	local data = self:GetPlayerDataMap();
	if (type(data) == "table") then
		local lp = self.Services.Players.LocalPlayer;
		for name, info in pairs(data) do
			if ((type(info) == "table") and (info.Role == "Murderer") and not info.Dead and (name ~= lp.Name)) then
				local pl = self.Services.Players:FindFirstChild(name);
				local char = pl and pl.Character;
				local root = char and self:GetRoot(char);
				local hum = char and char:FindFirstChildOfClass("Humanoid");
				if (root and (not hum or (hum.Health > 0))) then
					return root;
				end
			end
		end
	end
	for _, plr in ipairs(self.Services.Players:GetPlayers()) do
		if ((plr ~= self.Services.Players.LocalPlayer) and plr.Character and plr.Character:FindFirstChild("Knife")) then
			return self:GetRoot(plr.Character);
		end
	end
	return nil;
end;
Hub.PickBestCoin = function(self, pos, coins, mpos)
	if not (self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
		local best, bd = nil, math.huge;
		for _, v in ipairs(coins) do
			local d = (v.Position - pos).Magnitude;
			if (d < bd) then
				bd = d;
				best = v;
			end
		end
		return best;
	end
	local AVOID_DIST = 40;
	local safe, sd = nil, math.huge;
	local far, fd = nil, -1;
	for _, v in ipairs(coins) do
		local md = Vector3.new(v.Position.X - mpos.X, 0, v.Position.Z - mpos.Z).Magnitude;
		if (md > fd) then
			fd = md;
			far = v;
		end
		if (md >= AVOID_DIST) then
			local d = (v.Position - pos).Magnitude;
			if (d < sd) then
				sd = d;
				safe = v;
			end
		end
	end
	if safe then
		return safe;
	end
	if (far and (fd >= (AVOID_DIST * 0.6))) then
		return far;
	end
	return nil;
end;
Hub.AvoidSteer = function(self, cur, dest, mpos)
	if not (self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
		return dest;
	end
	local AVOID_DIST = 40;
	local dm = Vector3.new(cur.X - mpos.X, 0, cur.Z - mpos.Z).Magnitude;
	if (dm >= AVOID_DIST) then
		return dest;
	end
	local away = Vector3.new(cur.X - mpos.X, 0, cur.Z - mpos.Z);
	if (away.Magnitude < 0.1) then
		away = Vector3.new(1, 0, 0);
	end
	away = away.Unit;
	local want = Vector3.new(dest.X - cur.X, 0, dest.Z - cur.Z);
	local mag = want.Magnitude;
	if (mag < 0.1) then
		return dest;
	end
	local weight = 1 + ((1 - (dm / AVOID_DIST)) * 2);
	local blend = want.Unit + (away * weight);
	if (blend.Magnitude < 0.1) then
		blend = away;
	else
		blend = blend.Unit;
	end
	local np = cur + (blend * mag);
	return Vector3.new(np.X, dest.Y, np.Z);
end;
Hub.FarmStepMove = function(self, root, dest, dt, speed, mode)
	local dir = dest - root.Position;
	local dist = dir.Magnitude;
	local np = dest;
	if (dist > 0.05) then
		np = root.Position + (dir.Unit * math.min(speed * dt, dist));
	end
	local cf = CFrame.new(np);
	if (mode == LUAOBFUSACTOR_DECRYPT_STR_0("\55\48\180\14", "\94\115\95\195\96\46\175")) then
		cf = cf * CFrame.Angles(-math.pi * 0.5, 0, 0);
		self.AutoFarm.WasDown = true;
	end
	pcall(function()
		root.CFrame = cf;
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
end;
Hub.StartAutoFarmLoop = function(self)
	if self.AutoFarm.Connection then
		pcall(function()
			self.AutoFarm.Connection:Disconnect();
		end);
		self.AutoFarm.Connection = nil;
	end
	local DOWN_DEPTH = 14;
	local DOWN_RISE_XZ = 4;
	local RISE_SAFE_DIST = 20;
	pcall(function()
		local rep = self.Services.ReplicatedStorage;
		local remotes = rep:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\113\78\50\50\58\40\148", "\128\35\43\95\93\78\77\231"));
		local gp = remotes and remotes:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\131\28\59\49\7\114\168\189", "\201\196\125\86\84\119\30"));
		local csRem = gp and gp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\224\225\13\177\208\221\16\190\209\250\1\187", "\223\163\142\100"));
		if (csRem and csRem:IsA("RemoteEvent")) then
			local c = csRem.OnClientEvent:Connect(function()
				self.AutoFarm.Target = nil;
				self.AutoFarm.SawCoins = false;
				self.AutoFarm.CoinsDone = false;
			end);
			table.insert(self.State.Connections, c);
		end
	end);
	self.AutoFarm.Connection = self.Services.RunService.Stepped:Connect(function(_, dt)
		if not self.Config.Toggles.AutoFarm then
			return;
		end
		local lp = self.Services.Players.LocalPlayer;
		local char = lp and lp.Character;
		local root = char and self:GetRoot(char);
		local hum = char and char:FindFirstChildOfClass("Humanoid");
		if not (char and root and hum and (hum.Health > 0)) then
			self.AutoFarm.Target = nil;
			self.AutoFarm.WasDown = false;
			self:ReleaseFarm();
			return;
		end
		if (not self:IsRoundActive() or not self:IsPlayerInRound(lp) or (root.Position.Y > 350)) then
			self.AutoFarm.Target = nil;
			self.AutoFarm.WasDown = false;
			self:ReleaseFarm();
			return;
		end
		local function finish()
			self.AutoFarm.Target = nil;
			self:ReleaseFarm();
			if not self.AutoFarm.CoinsDone then
				self.AutoFarm.CoinsDone = true;
				if self.Config.Toggles.AutoFarmKillAllOnFull then
					task.spawn(function()
						task.wait(0.05);
						local knife = self:FindKnife();
						if knife then
							self:ExecuteKillAll();
						end
					end);
				end
				if self.Config.Toggles.AutoFarmShootMurdererOnFull then
					task.spawn(function()
						task.wait(0.05);
						local gun = self:FindGun();
						if gun then
							self:ShootMurderer();
						end
					end);
				end
				if self.Config.Toggles.AutoFarmAutoReset then
					pcall(function()
						hum.Health = 0;
					end);
				elseif self.Config.Toggles.AutoFarmSafeZone then
					local lobbySpawns = self.Services.Workspace:FindFirstChild("RegularLobby") and self.Services.Workspace.RegularLobby:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\177\6\194\166\182\145", "\216\226\118\163\209"));
					local lobbyPart = lobbySpawns and lobbySpawns:GetChildren()[1];
					local lobbyTarget = (lobbyPart and (lobbyPart.Position + Vector3.new(0, 4, 0))) or Vector3.new(23, 506, -17);
					root.CFrame = CFrame.new(lobbyTarget);
				end
			end
		end
		if (self.AutoFarm.SawCoins and self:IsCoinBagFull()) then
			finish();
			return;
		end
		local coins = self:GetAvailableCoins();
		if (#coins > 0) then
			self.AutoFarm.SawCoins = true;
			if self.AutoFarm.CoinsDone then
				self.AutoFarm.CoinsDone = false;
			end
			local mRoot = (self.Config.Toggles.AutoFarmAvoidMurder and self:GetMurdererHRP()) or nil;
			local mpos = (mRoot and mRoot.Position) or nil;
			local curTarget = self.AutoFarm.Target;
			local targetValid = curTarget and curTarget.Parent and not curTarget:GetAttribute("Collected") and not curTarget:GetAttribute("Delete");
			if (targetValid and self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
				local md = Vector3.new(curTarget.Position.X - mpos.X, 0, curTarget.Position.Z - mpos.Z).Magnitude;
				if (md < 24) then
					targetValid = false;
				end
			end
			if not targetValid then
				self.AutoFarm.Target = self:PickBestCoin(root.Position, coins, mpos);
			end
			local farmMode = self.Config.Values.AutoFarmMode or "Basic";
			local speed = 23;
			if self.AutoFarm.Target then
				self:SetFarmNoClip(true);
				local cpos = self.AutoFarm.Target.Position;
				self.AutoFarm.DownRefY = cpos.Y;
				local dest = cpos;
				if (farmMode == "Down") then
					local xz = Vector3.new(root.Position.X - cpos.X, 0, root.Position.Z - cpos.Z).Magnitude;
					local safeToRise = not mpos or (Vector3.new(root.Position.X - mpos.X, 0, root.Position.Z - mpos.Z).Magnitude > RISE_SAFE_DIST);
					if ((xz <= DOWN_RISE_XZ) and safeToRise) then
						dest = cpos;
						self:FireCoinTouch(self.AutoFarm.Target);
					else
						dest = Vector3.new(cpos.X, cpos.Y - DOWN_DEPTH, cpos.Z);
					end
				elseif ((cpos - root.Position).Magnitude <= 6) then
					self:FireCoinTouch(self.AutoFarm.Target);
				end
				dest = self:AvoidSteer(root.Position, dest, mpos);
				self:FarmStepMove(root, dest, dt, speed, farmMode);
			elseif mpos then
				self:SetFarmNoClip(true);
				local away = Vector3.new(root.Position.X - mpos.X, 0, root.Position.Z - mpos.Z);
				if (away.Magnitude < 0.1) then
					away = Vector3.new(1, 0, 0);
				end
				away = away.Unit;
				local y = root.Position.Y;
				if ((farmMode == "Down") and self.AutoFarm.DownRefY) then
					y = self.AutoFarm.DownRefY - DOWN_DEPTH;
				end
				self:FarmStepMove(root, root.Position + (away * 40) + Vector3.new(0, y - root.Position.Y, 0), dt, speed, farmMode);
			end
		else
			self.AutoFarm.Target = nil;
			self:ReleaseFarm();
			if (self.AutoFarm.SawCoins and not self.AutoFarm.CoinsDone) then
				finish();
			end
		end
	end);
end;
Hub.FormatNumber = function(self, num)
	local n = tonumber(num) or 0;
	local sign = ((n < 0) and "-") or "";
	local absN = math.abs(n);
	local intPart = math.floor(absN);
	local decPart = absN - intPart;
	local formatted = tostring(intPart);
	local k;
	while true do
		formatted, k = formatted:gsub("^(-?%d+)(%d%d%d)", LUAOBFUSACTOR_DECRYPT_STR_0("\251\161\87\68\5", "\95\222\144\123\97\55\16"));
		if (k == 0) then
			break;
		end
	end
	if (decPart >= 0.01) then
		local decStr = string.format("%.2f", decPart):sub(2);
		decStr = decStr:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\73\207\254", "\131\121\228\218\35"), "");
		if (decStr ~= ".") then
			return sign .. formatted .. decStr;
		end
	end
	return sign .. formatted;
end;
Hub.CountTable = function(self, tbl)
	local c = 0;
	if (type(tbl) == "table") then
		for _ in pairs(tbl) do
			c = c + 1;
