Hub.IsVotingActive = function(self)
	local lobby = self:GetLobby();
	if not lobby then
		return false;
	end
	if (self.Services.Workspace:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\138\94\47", "\124\199\63\95\168\212\107\196")) or self.Services.Workspace:FindFirstChild("Normal")) then
		return false;
	end
	local pad = lobby:FindFirstChild("VotePad1");
	if not pad then
		return false;
	end
	local vig = pad:FindFirstChild("VoteInfoGui");
	if vig then
		if (vig:IsA("BillboardGui") or vig:IsA("SurfaceGui")) then
			if not vig.Enabled then
				return false;
			end
		end
		local mn = vig:FindFirstChild("MapName", true);
		if (mn and mn:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\50\173\75\46\136\246\139\246\10", "\147\102\200\51\90\196\151\233"))) then
			local t = mn.Text:gsub("%s+", "");
			if ((t == "") or (t == "Map")) then
				return false;
			end
		end
	end
	return true;
end;
Hub.ScanMaps = function(self)
	local lobby = self:GetLobby();
	local pads = {LUAOBFUSACTOR_DECRYPT_STR_0("\13\255\251\200\142\225\63\106", "\91\91\144\143\173\222\128"),"VotePad2","VotePad3"};
	local result = {};
	for _, padName in ipairs(pads) do
		local pad = lobby and lobby:FindFirstChild(padName);
		local mapName = "";
		local votes = "";
		local imageId = "";
		if pad then
			local vig = pad:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\21\175\88\84\130\64\37\175\107\68\162", "\46\67\192\44\49\203"));
			if vig then
				local mn = vig:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\41\215\62\140\37\169\0", "\101\100\182\78\194\68\196"), true);
				if (mn and mn:IsA("TextLabel") and (mn.Text ~= "")) then
					mapName = mn.Text;
				end
				local vt = vig:FindFirstChild("Votes", true);
				if (vt and vt:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\124\77\40\225\161\74\122\208\68", "\181\40\40\80\149\237\43\24")) and (vt.Text ~= "")) then
					votes = vt.Text;
				end
			end
			local mig = pad:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\56\179\53\27\180\76\29\50\167\44", "\114\117\210\69\82\218\42"));
			if mig then
				local mi = mig:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\105\215\72\90\175\75\216", "\204\36\182\56\19"), true);
				if (mi and mi:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\192\70\221\132\120\20\19\235\78\208", "\114\137\43\188\227\29\88")) and (mi.Image ~= "")) then
					imageId = mi.Image;
				end
			end
			local voteIcons = lobby:FindFirstChild("VoteIcons");
			if voteIcons then
				local viPad = voteIcons:FindFirstChild(padName);
				if viPad then
					local img = viPad:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\205\16\169\23\225\49\169\18\225\17", "\112\132\125\200"), true);
					if (img and (img.Image ~= "")) then
						imageId = img.Image;
					end
				end
			end
		end
		if not self.Maps.Cached[padName] then
			self.Maps.Cached[padName] = {MapName=padName,[LUAOBFUSACTOR_DECRYPT_STR_0("\203\183\231\118\73", "\149\157\216\147\19\58")]="0",Image=Icons.MapFallback};
		end
		if ((mapName ~= "") and (mapName ~= "Unknown Map")) then
			self.Maps.Cached[padName].MapName = mapName;
		end
		if (votes ~= "") then
			self.Maps.Cached[padName].Votes = votes;
		end
		if (imageId ~= "") then
			self.Maps.Cached[padName].Image = imageId;
		end
		table.insert(result, {[LUAOBFUSACTOR_DECRYPT_STR_0("\249\135\28\230\200\139\29", "\168\169\230\120")]=padName,Pad=pad,MapName=self.Maps.Cached[padName].MapName,Votes=self.Maps.Cached[padName].Votes,Image=self.Maps.Cached[padName].Image});
	end
	return result;
end;
Hub.TeleportToPad = function(self, padName)
	if not self:IsVotingActive() then
		return;
	end
	local lobby = self:GetLobby();
	local pad = lobby and lobby:FindFirstChild(padName);
	if not pad then
		return;
	end
	local targetPart = pad:FindFirstChild("Pad") or pad:FindFirstChildWhichIsA("BasePart");
	local lp = self.Services.Players.LocalPlayer;
	local char = lp.Character;
	local root = self:GetRoot(char);
	if (targetPart and root) then
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.CFrame = targetPart.CFrame + Vector3.new(0, 3.5, 0);
		if firetouchinterest then
			pcall(function()
				firetouchinterest(root, targetPart, 0);
				firetouchinterest(root, targetPart, 1);
			end);
		end
	end
end;
Hub.StartVoteDuplicator = function(self)
	if self.Maps.DupRunning then
		return;
	end
	self.Maps.DupRunning = true;
	task.spawn(function()
		while self.Config.Toggles.VoteDup and self.State.Gui and self.State.Gui.Parent do
			if not self:IsVotingActive() then
				if self.Maps.StatusLabel then
					self.Maps.StatusLabel.Text = "Статус: Ожидание голосования...";
					self.Maps.StatusLabel.TextColor3 = self.Theme.TextMuted;
				end
				task.wait(0.4);
			else
				local padName = self.Maps.SelectedPad;
				if not padName then
					if self.Maps.StatusLabel then
						self.Maps.StatusLabel.Text = "Статус: Нажмите на карту ниже для запуска дюпа";
						self.Maps.StatusLabel.TextColor3 = self.Theme.HeroYellow;
					end
					task.wait(0.2);
				else
					self:UpdateMapCardsHighlight();
					if self.Maps.StatusLabel then
						local mapName = (self.Maps.Cached[padName] and self.Maps.Cached[padName].MapName) or padName;
						self.Maps.StatusLabel.Text = "Статус: Дюп голосов для " .. tostring(mapName) .. LUAOBFUSACTOR_DECRYPT_STR_0("\178\195\202", "\119\156\237\228");
						self.Maps.StatusLabel.TextColor3 = self.Theme.InnocentGreen;
					end
					local lp = self.Services.Players.LocalPlayer;
					local char = lp.Character;
					local hum = char and char:FindFirstChildOfClass("Humanoid");
					local root = self:GetRoot(char);
					if (root and hum and (hum.Health > 0)) then
						self:TeleportToPad(padName);
						task.wait(0.22);
						if (self.Config.Toggles.VoteDup and self:IsVotingActive() and (self.Maps.SelectedPad == padName)) then
							hum.Health = 0;
						end
					end
					local deadChar = char;
					local timeout = 0;
					while self.Config.Toggles.VoteDup and self:IsVotingActive() and (timeout < 80) do
						local curChar = lp.Character;
						if (curChar and (curChar ~= deadChar) and curChar:FindFirstChild("HumanoidRootPart")) then
							break;
						end
						task.wait(0.03);
						timeout = timeout + 1;
					end
					task.wait(0.08);
				end
			end
		end
		self.Maps.DupRunning = false;
	end);
end;
Hub.UpdateMapCardsHighlight = function(self)
	for padName, cardData in pairs(self.Maps.Cards) do
		if (cardData and cardData.CardStroke) then
			if (self.Maps.SelectedPad == padName) then
				cardData.CardStroke.Color = self.Theme.InnocentGreen;
				cardData.CardStroke.Thickness = 2;
			else
				cardData.CardStroke.Color = self.Theme.Border;
				cardData.CardStroke.Thickness = 1;
			end
		end
	end
end;
